fn starts_with(s: &[char], p: &[char]) -> bool {
    // Precondition: p must be a valid slice of characters
    // Postcondition: returns true if s starts with p, false otherwise
    // Ensures: If p is empty, the result is true.
    // Ensures: If s is shorter than p, the result is false.
    // Ensures: If s is at least as long as p, the result is true if all characters match.
    requires!(p.len() >= 0);
    ensures!(p.is_empty() ==> result == true);
    ensures!(s.len() < p.len() ==> result == false);
    ensures!(s.len() >= p.len() ==> (result == s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc)));

    if p.is_empty() {
        return true; // An empty prefix matches any sequence
    }
    if s.len() < p.len() {
        return false; // Sequence is shorter than the prefix
    }
    s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc) // Check if all characters match
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Precondition: v and p must be valid vectors of characters
    // Postcondition: returns true if v starts with p, false otherwise
    requires!(v.len() >= 0 && p.len() >= 0);
    ensures!(result == starts_with(v.as_slice(), p.as_slice()));

    starts_with(v, p)
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    // Precondition: xs must be a valid vector of vectors of characters
    // Postcondition: returns a vector containing only those sequences from xs that start with p
    requires!(p.len() >= 0);
    ensures!(result.len() <= xs.len()); // The result can be at most the size of xs
    ensures!(result.iter().all(|seq| has_prefix(seq, &p))); // All sequences in result must have the prefix p

    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect() // Collect the filtered sequences into a new Vec
}

